(async()=>{
const r=__shellReview,m=r.motion,$=id=>document.getElementById(id);let now=performance.now();
const tick=(n=1)=>{for(let i=0;i<n;i++){now+=50;m.update(now);}};
const eq=(a,b)=>a.length===b.length&&a.every((v,i)=>Math.abs(v-b[i])<1e-7);
const assert=(v,msg)=>{if(!v)throw Error(msg);};
$('side').click();const camera=r.camera.position.toArray();const results=[];
for(const mode of ['closed','cut','internal']){
$(mode).click();m.reset();assert(r.inspect().layoutMode===mode,'reset layout');assert(eq(camera,r.camera.position.toArray()),'reset camera');
m.release();tick(25);assert(m.state.action==='shoot','shoot started');assert(eq(camera,r.camera.position.toArray()),'shoot camera');
const before=m.inspect();m.state.paused=true;tick(20);assert(m.inspect().outerAngle===before.outerAngle&&m.inspect().coreEmission===before.coreEmission,'pause frozen');
m.state.paused=false;tick(80);assert(m.state.action==='idle','shoot complete');assert(m.inspect().glassEmission===0,'glass is passive');
const old=m.inspect().activeId;m.reload();tick(24);assert(m.inspect().lidAngle<0&&m.inspect().lowerLidAngle>0,'two lids');assert(r.inspect().layoutMode===mode,'reload layout');
tick(100);assert(m.state.action==='idle'&&m.inspect().activeId!==old,'new cartridge');assert(eq(camera,r.camera.position.toArray()),'reload camera');results.push(mode);
}
m.reset();const light=[];for(const q of [0,.25,.5,.75,1]){m.state.charge=q;tick(40);light.push(m.inspect().coreEmission);assert(m.inspect().glassEmission===0,'glass emission');}assert(light.every((v,i)=>i===0||v>light[i-1]),'monotonic light');
$('clay').click();tick(2);$('cut').click();$('clay').click();tick(2);const crystal=r.interior.modules.find(x=>x.id==='core').group.children.find(o=>o.geometry?.type==='IcosahedronGeometry');assert(crystal.material.emissiveIntensity>1.4,'core survives grey/layout');
m.reset();$('cell').click();tick(30);const socket=r.interior.modules.find(x=>x.id==='cell').group.children.find(o=>o.position.x===-1.42);assert(socket&&socket.parent.position.x===0,'socket stays fixed');assert($('reload').disabled,'manual cell locks reload');
m.reset();$('auto').click();tick(30);assert(eq(camera,r.camera.position.toArray()),'auto camera');$('pause').click();const autoTime=m.state.actionTime;tick(10);assert(m.state.actionTime===autoTime,'auto pause');$('internal').click();assert(m.state.paused,'layout preserves pause');$('motionReset').click();assert(!m.state.auto&&!m.state.paused&&m.state.action==='idle','reset clears action');assert(eq(camera,r.camera.position.toArray()),'all actions camera');
// Sample the cartridge extraction envelope against the actual open tail-shell triangles.
const THREE=await import('three');m.reload();m.state.actionTime=.62;m.state.paused=true;tick();r.model.root.updateMatrixWorld(true);
const objects=[];r.model.root.traverse(o=>{if(o.isMesh&&(/tail shell|tail lid|drum closure|drum access|tail hinge/.test(o.name)))objects.push(o);});
const hits=[];for(let i=0;i<32;i++){const a=i*Math.PI/16;const ray=new THREE.Raycaster(new THREE.Vector3(-1.73,.37*Math.cos(a),.37*Math.sin(a)),new THREE.Vector3(-1,0,0),0,3);const h=ray.intersectObjects(objects,false);if(h.length)hits.push({sample:i,part:h[0].object.name,x:h[0].point.x});}
assert(hits.length===0,'cartridge extraction envelope obstructed');m.reset();return {modes:results,light,cameraPreserved:true,pauseReset:true,greyRestore:true,extractionEnvelopeHits:hits};
})()
